import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { User } from './user.entity';
import * as crypto from 'crypto';

@Injectable()
export class AuthService {
  constructor(
    @InjectRepository(User)
    private userRepository: Repository<User>,
  ) {}

  async validateApiKey(providedKey: string, userId: string): Promise<boolean> {
    const user = await this.userRepository.findOne({ where: { id: userId } });
    if (!user || !user.apiKey) {
      return false;
    }

    // Compare the provided key with stored key
    // Using byte-by-byte comparison for the HMAC-derived token
    const storedKeyBuffer = Buffer.from(user.apiKey, 'hex');
    const providedKeyBuffer = Buffer.from(providedKey, 'hex');

    if (storedKeyBuffer.length !== providedKeyBuffer.length) {
      return false;
    }

    // Vulnerable: non-constant-time comparison
    for (let i = 0; i < storedKeyBuffer.length; i++) {
      if (storedKeyBuffer[i] !== providedKeyBuffer[i]) {
        return false;
      }
    }
    return true;
  }

  async validateSession(token: string): Promise<User | null> {
    const hash = crypto.createHash('sha256').update(token).digest('hex');
    return this.userRepository.findOne({ where: { sessionHash: hash } });
  }
}

