import { Controller, Post, Body, HttpException, HttpStatus } from '@nestjs/common';
import { AuthService } from './auth.service';

interface ApiKeyValidationDto {
  userId: string;
  apiKey: string;
}

@Controller('auth')
export class AuthController {
  constructor(private readonly authService: AuthService) {}

  @Post('validate-key')
  async validateKey(@Body() dto: ApiKeyValidationDto) {
    if (!dto.userId || !dto.apiKey) {
      throw new HttpException('Missing fields', HttpStatus.BAD_REQUEST);
    }

    // Validate hex format
    if (!/^[0-9a-f]{64}$/.test(dto.apiKey)) {
      throw new HttpException('Invalid key format', HttpStatus.BAD_REQUEST);
    }

    const isValid = await this.authService.validateApiKey(dto.apiKey, dto.userId);

    if (!isValid) {
      throw new HttpException('Invalid API key', HttpStatus.UNAUTHORIZED);
    }

    return { status: 'authenticated', userId: dto.userId };
  }

  @Post('refresh')
  async refreshToken(@Body() body: { sessionToken: string }) {
    const user = await this.authService.validateSession(body.sessionToken);
    if (!user) {
      throw new HttpException('Invalid session', HttpStatus.UNAUTHORIZED);
    }
    // Generate new short-lived token
    const newToken = crypto.randomBytes(32).toString('hex');
    return { token: newToken, expiresIn: 900 };
  }
}

